def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    op = [h[1] for h in history]
    my = [h[0] for h in history]

    op_c = 0
    for x in op:
        if x == 'C':
            op_c += 1
    op_d = n - op_c

    # Defect on last round only if opponent has shown defection; otherwise
    # mutual cooperation payoff (3) beats risking the temptation grab.
    if n >= 99:
        if op_d == 0:
            return 'C'
        return 'D'

    # Very early: cooperate, but retaliate immediately if exploited.
    if n < 6:
        if op[-1] == 'D':
            return 'D'
        return 'C'

    # Count short-window stats.
    k = 5 if n >= 5 else n
    recent_op = op[-k:]
    recent_d = 0
    for x in recent_op:
        if x == 'D':
            recent_d += 1

    k10 = 10 if n >= 10 else n
    op10 = op[-k10:]
    d10 = 0
    for x in op10:
        if x == 'D':
            d10 += 1

    # Opponent never defected: harvest with a single defection, then keep
    # cooperating to lock in mutual reward. A single uncountered D gives +5
    # versus +3, so time it well before the end.
    if op_d == 0:
        if n == 60:
            return 'D'
        return 'C'

    # Aggressive opponent: many defections overall. Defect most of the time
    # but probe occasionally to reestablish cooperation.
    if op_d * 2 > n:
        # If they just cooperated, offer one cooperation to test.
        if op[-1] == 'C':
            if recent_d >= 3:
                return 'D'
            return 'C'
        # Opponent defected.
        if recent_d >= 4:
            return 'D'
        # Occasionally forgive to escape mutual-defection trap.
        if rng.random() < 0.12:
            return 'C'
        return 'D'

    # Opponent mostly cooperates but has defected sometimes.
    if op_d * 4 < n:
        # Recent exploitative streak: retaliate until they return to C,
        # with a single-round forgiveness probe to break cycles.
        if recent_d >= 3:
            return 'D'
        if recent_d == 2:
            if op[-1] == 'C':
                return 'C'
            return 'D'
        if recent_d == 1:
            if op[-1] == 'D':
                # Retaliate once, then resume cooperation.
                return 'D'
            # Opportunistic exploitation if opponent is very forgiving.
            if d10 == 1 and rng.random() < 0.08:
                return 'D'
            return 'C'
        # recent_d == 0: full cooperation. Rare probe to test exploitable
        # opponents, particularly late enough that a counterattack costs little.
        if n >= 20 and n % 17 == 0 and rng.random() < 0.2:
            return 'D'
        return 'C'

    # Mixed opponent. Retaliate on defection, forgive after cooperation.
    if op[-1] == 'D':
        if recent_d >= 3:
            return 'D'
        if rng.random() < 0.25:
            return 'C'
        return 'D'
    # Opponent cooperated: reciprocate, but probe mixed opponents lightly.
    if d10 >= 4:
        # Still risky: probe rarely.
        if rng.random() < 0.1:
            return 'D'
        return 'C'
    if n % 13 == 0 and rng.random() < 0.15:
        return 'D'
    return 'C'
